<script setup lang="ts">
import { computed, ref } from 'vue'
import { useQuery, useQueryClient } from '@tanstack/vue-query'
import { api } from '@/api/client'
type Item={id:number;name:string;quantity_available:number};type Rental={id:number;inventory_item_id:number;quantity:number;due_at?:string;status:string};type Player={id:number;name:string;email:string}
const client=useQueryClient();const facilityId=ref<number>();const branchId=ref<number>();const itemName=ref('');const quantity=ref<number>();const price=ref<number>();const selectedItem=ref<number>();const selectedPlayer=ref<number>();const rentalQuantity=ref(1);const dueAt=ref('');const message=ref('');const error=ref('');const busy=ref(false)
const facilities=useQuery({queryKey:['facilities'],queryFn:async()=>((await api.get('/facilities')).data.data??[])});const branches=useQuery({queryKey:computed(()=>['rental-branches',facilityId.value]),enabled:computed(()=>!!facilityId.value),queryFn:async()=>((await api.get(`/facilities/${facilityId.value}/branches`)).data.data??[])});const items=useQuery({queryKey:['inventory-items'],queryFn:async()=>{const r=await api.get('/inventory-items');return r.data.data?.data??r.data.data??[]}});const players=useQuery({queryKey:['rental-users'],queryFn:async()=>{const r=await api.get('/rental-users');return r.data.data??[]}});const rentals=useQuery({queryKey:['rentals'],queryFn:async()=>{const r=await api.get('/rentals');return r.data.data?.data??r.data.data??[]}});const overdue=useQuery({queryKey:['rentals-overdue'],queryFn:async()=>{const r=await api.get('/rentals/overdue');return r.data.data?.data??r.data.data??[]}});const itemList=computed<Item[]>(()=>items.data.value??[]);const playerList=computed<Player[]>(()=>players.data.value??[]);const rentalList=computed<Rental[]>(()=>rentals.data.value??[])
async function refresh(){await Promise.all([client.invalidateQueries({queryKey:['inventory-items']}),client.invalidateQueries({queryKey:['rentals']})])}async function addItem(){if(!branchId.value||!itemName.value||quantity.value===undefined||price.value===undefined){error.value='Select a branch and enter item details.';return}busy.value=true;try{await api.post('/inventory-items',{branch_id:branchId.value,name:itemName.value,quantity_total:quantity.value,rental_price:price.value});message.value='Inventory item created.';itemName.value='';await refresh()}catch(e:any){error.value=e.response?.data?.message??'Item could not be created.'}finally{busy.value=false}}async function checkout(){if(!selectedItem.value||!selectedPlayer.value){error.value='Select an item and player.';return}busy.value=true;try{await api.post('/rentals',{inventory_item_id:selectedItem.value,user_id:selectedPlayer.value,quantity:rentalQuantity.value,due_at:dueAt.value||undefined});message.value='Rental checked out.';await refresh()}catch(e:any){error.value=e.response?.data?.message??'Rental could not be created.'}finally{busy.value=false}}async function action(r:Rental,mode:'return'|'extend'|'close'){const value=mode==='extend'?prompt('New due date (YYYY-MM-DDTHH:mm)'):mode==='close'?prompt('Damage fee','0'):null;if((mode==='extend'&&!value)||(mode==='close'&&value===null))return;try{await api.post(`/rentals/${r.id}/${mode}`,mode==='extend'?{due_at:value}:mode==='close'?{damage_fee:Number(value)}:undefined);message.value=`Rental ${mode}ed.`;await refresh()}catch(e:any){error.value=e.response?.data?.message??'Rental action failed.'}}</script>
<template><header class="page-header"><div><p class="eyebrow">EQUIPMENT</p><h1>Rentals</h1><p class="muted">Track inventory and front-desk rentals.</p></div></header><p v-if="message" class="action-message success">{{message}}</p><p v-if="error" class="action-message error">{{error}}</p><section class="membership-top-grid"><article class="panel membership-form"><h2>Add inventory</h2><form @submit.prevent="addItem"><div class="form-grid"><label>Facility<select v-model.number="facilityId" @change="branchId=undefined"><option :value="undefined">Select facility</option><option v-for="facility in facilities.data.value??[]" :key="facility.id" :value="facility.id">{{facility.name}}</option></select></label><label>Branch<select v-model.number="branchId" :disabled="!facilityId"><option :value="undefined">Select branch</option><option v-for="branch in branches.data.value??[]" :key="branch.id" :value="branch.id">{{branch.name}}</option></select></label><label>Item name<input v-model="itemName"/></label><label>Quantity<input v-model.number="quantity" type="number" min="0"/></label><label>Rental price<input v-model.number="price" type="number" min="0"/></label></div><button class="secondary-button">Add item</button></form></article><article class="panel membership-form"><h2>Check out</h2><form @submit.prevent="checkout"><label>Player<select v-model.number="selectedPlayer"><option :value="undefined">Select player</option><option v-for="player in playerList" :key="player.id" :value="player.id">{{player.name}} · {{player.email}}</option></select></label><label>Inventory item<select v-model.number="selectedItem"><option :value="undefined">Select item</option><option v-for="item in itemList" :key="item.id" :value="item.id">{{item.name}} · {{item.quantity_available}} available</option></select></label><label>Quantity<input v-model.number="rentalQuantity" type="number" min="1"/></label><label>Due at<input v-model="dueAt" type="datetime-local"/></label><button class="primary-button">Check out</button></form></article></section><section class="panel"><h2>Overdue rentals</h2><p class="muted">{{overdue.data.value?.length??0}} active overdue rental(s).</p></section><section class="panel memberships-table"><h2>Active and past rentals</h2><div class="table-wrap"><table><thead><tr><th>Rental</th><th>Item</th><th>Quantity</th><th>Due</th><th>Status</th><th>Action</th></tr></thead><tbody><tr v-for="rental in rentalList" :key="rental.id"><td>#{{rental.id}}</td><td>{{itemList.find(item=>item.id===rental.inventory_item_id)?.name??`Item #${rental.inventory_item_id}`}}</td><td>{{rental.quantity}}</td><td>{{rental.due_at||'—'}}</td><td>{{rental.status}}</td><td><button v-if="rental.status==='active'" class="table-button" @click="action(rental,'return')">Return</button> <button v-if="rental.status==='active'" class="table-button" @click="action(rental,'extend')">Extend</button> <button v-if="rental.status==='active'" class="table-button cancel" @click="action(rental,'close')">Close/damage</button></td></tr></tbody></table></div></section></template>
